         │
         ├── Implementations of storage.Queryable:
         │     ├── fanout.Querier (storage/fanout.go)
         │     ├── remote/Storage.Querier (storage/remote/storage.go)
         │     ├── remote/sampleAndChunkQueryableClient.Querier (storage/remote/read.go)
